use vstd::prelude::*;

verus! {

fn imag(val: Vec<(f64, f64)>) -> Vec<f64>
    ensures
        val.len() == result.len(),
        // For every valid index i, result[i] == val[i].1 (the imaginary part)
        forall(|i: usize| (i < val.len()) ==> result[i] == val[i].1),
        // If the imaginary part is zero, result[i] == 0.0 exactly
        forall(|i: usize| (i < val.len() && val[i].1 == 0.0) ==> result[i] == 0.0),
        // If val[i] is not the zero complex number (real or imag != 0.0),
        // then result[i] equals the imaginary part
        forall(|i: usize| (
            i < val.len() && (val[i].0 != 0.0 || val[i].1 != 0.0)
         ) ==> result[i] == val[i].1),
{
    let n = val.len();
    let mut res = Vec::with_capacity(n);
    let mut i = 0;
    while i < n
        invariant i <= n,
        invariant res.len() == i,
        invariant forall(|j: usize| (j < i) ==> res[j] == val[j].1),
        decreases n - i,
    {
        let imag_part = val[i].1;
        res.push(imag_part);
        i += 1;
    }
    res
}

} 
fn main() {}

